    "# Monthly sales trend\n",
    "df['YearMonth'] = df['OrderDate'].dt.to_period('M')\n",
    "monthly_sales = df.groupby('YearMonth')['TotalPrice'].sum().sort_values(ascending=True)\n",
    "print(\"\\nMonthly Sales Trend (KSh):\")\n",
    "print(monthly_sales)"
